}

const kinds = {
  singleton: ['about_hero','about_wide_banner','blog_hero','education_hero','contact_hero','bespoke_showcase','collection_page','hiphop_showcase'],
  content_list: ['about_values','about_timeline','about_founders','contact_info','bespoke_process','bespoke_manufacturing'],
  home_group1: ['hero','collection','certifications','discover_shapes','bestsellers','shop_by_category'],
  relational: ['checkout_result','promotion','service_banner','summary','announcement','faq'],
  article: ['blog','education'],
} as const
/** Explicit wire/snapshot correspondence. Unmapped arguments remain scanned at
 * their original paths, so adding an argument cannot silently bypass admission. */
export function cmsVideoProjection(name: CmsCommand, supplied: Record<string, unknown>, previous: unknown) {
  const mappings: Partial<Record<CmsCommand, Record<string, string>>> = {
    cms_save_singleton_v1: { p_item: 'item' },
    cms_save_content_list_v1: { p_items: 'items' },
    cms_save_home_group1_v1: { p_section: 'section', p_items: 'items' },
    cms_save_relational_v1: { p_parent: 'parent', p_items: 'items' },
    cms_save_reels_v1: { p_section: 'section', p_items: 'items' },
    cms_save_article_v1: { p_post: 'post', p_tags: 'tags', p_products: 'products', p_blocks: 'content_blocks' },
    cms_save_docs_page_v1: { p_page: 'page', p_blocks: 'blocks' },
    bespoke_hero_save_v1: { p_item: 'item', p_items: 'items' },
    bespoke_form_save_v1: { p_settings: 'settings' },
    cms_save_support_faq_category_v1: { p_item: 'item' },
  }
  const mapping = mappings[name]
  if (!mapping) throw new Error('Unsupported video projection')
  const next = Object.fromEntries(Object.entries(supplied).map(([key, value]) => [mapping[key] ?? key, value]))
  if (name === 'bespoke_form_save_v1') {
    const lists = supplied.p_lists
    if (!lists || typeof lists !== 'object' || Array.isArray(lists)) throw new Error('Invalid form lists')
    delete next.p_lists
    for (const [key, value] of Object.entries(lists)) {
      if (['guarantees','pieceTypes','stoneOptions','caratOptions','metalOptions'].includes(key)) next[key] = value
      else next['p_lists/' + key] = value
    }
  }
  if (name === 'cms_save_support_faq_category_v1') {
    if (!Array.isArray(previous)) throw new Error('Invalid FAQ categories')
    const matches = previous.filter(row => String(row.id) === String(supplied.p_id))
    if (matches.length > 1) throw new Error('Ambiguous FAQ category')
    previous = { item: matches[0] ?? null }
  }
  if (name === 'cms_save_relational_v1' && supplied.p_kind === 'faq') {
    const qualify = (items: unknown) => Array.isArray(items) ? items.map(item => ({ ...item,
      id: JSON.stringify([item.id ?? null, item.category_id ?? null, item.catalog_category_id ?? null]) })) : items
    next.items = qualify(next.items)
    if (previous && typeof previous === 'object' && !Array.isArray(previous)) {
      const record = previous as Record<string, unknown>
      previous = { ...record, items: qualify(record.items) }
    }
  }
  return { next, previous }
}
export function createCmsRepository(db: DbExecutor, actor?: AdminActor) {
  async function execute<K extends CmsCommand>(name: K, input: CmsArguments[K]): Promise<CmsResults[K]> {
    const routine = cmsRoutines[name]
    if (!routine) throw new Error('Unsupported CMS command')
    const supplied = input as Record<string, unknown>
    if ('p_kind' in supplied) {
      const group = Object.keys(kinds).find(key => name.includes(key)) as keyof typeof kinds | undefined
      if (!group || !(kinds[group] as readonly unknown[]).includes(supplied.p_kind)) throw new Error('Unsupported CMS kind')
    }
    assertSafeCmsIds(input)
    if (name.includes('save') && videoReferenceSlots(input).size) {
      const snapshots: Record<string, string> = {
        cms_save_singleton_v1: 'cms_singleton_snapshot_v1', cms_save_content_list_v1: 'cms_content_list_snapshot_v1',
        cms_save_home_group1_v1: 'cms_home_group1_snapshot_v1', cms_save_relational_v1: 'cms_relational_snapshot_v1',
        cms_save_reels_v1: 'cms_reels_snapshot_v1', cms_save_article_v1: 'cms_article_snapshot_v1',
        cms_save_docs_page_v1: 'cms_docs_snapshot_v1', bespoke_hero_save_v1: 'bespoke_hero_snapshot_v1', bespoke_form_save_v1: 'bespoke_form_snapshot_v1',
        cms_save_support_faq_category_v1: 'cms_support_faq_categories_v1',
      }
      const snapshot = snapshots[name] as CmsCommand | undefined
      if (!snapshot) throw new Error('Unsupported video save')
      const spec = cmsRoutines[snapshot]
      const params = Object.fromEntries(spec.args.map(key => [key, supplied[key]]))
      const previous = await execute(snapshot, params as CmsArguments[typeof snapshot])
      const projection = cmsVideoProjection(name, supplied, previous)
      await enforceVideoSave(db, projection.next, projection.previous)
    }
    const values = routine.args.map((key, index) => {
      const value = key === 'p_actor_id' ? actor?.profileId : supplied[key]
      if (value === undefined) throw new Error('Missing trusted actor or CMS argument')
      if (routine.types[index] === 'bigint' && value !== null && !(typeof value === 'string' && /^[1-9][0-9]*$/.test(value) && BigInt(value) <= BigInt('9223372036854775807')) && !(typeof value === 'number' && Number.isSafeInteger(value) && value > 0)) throw new Error('Invalid CMS identifier')
      return routine.types[index] === 'jsonb' ? JSON.stringify(value) : value
    })
    const { rows } = await db.query<{ result: unknown }>(`WITH snapshot AS MATERIALIZED (${routine.sql}) SELECT result::text AS result FROM snapshot`, values)
    const result = parseCmsJson(rows[0]?.result)
    if (rows.length !== 1 || !result || typeof result !== 'object') throw new Error('Invalid CMS result')
    if (name === 'cms_support_faq_categories_v1') {
      if (!Array.isArray(result)) throw new Error('Invalid FAQ categories')
    } else {
      if (Array.isArray(result)) throw new Error('Invalid CMS snapshot')
      const record = result as CmsRecord
      if (name === 'cms_save_support_faq_category_v1') {
        const category = record.category as CmsRecord | undefined
        if (!category || typeof category._revision !== 'string' || !/^[a-f0-9]{32}$/.test(category._revision)) throw new Error('Invalid FAQ category')
      } else if (!name.includes('delete_') && (typeof record.revision !== 'string' || !/^[a-f0-9]{32}$/.test(record.revision))) throw new Error('Invalid CMS revision')
      if (name.includes('delete_') && record.ok !== true) throw new Error('Invalid CMS deletion')
    }
    if (!Array.isArray(result)) {
      const record = result as CmsRecord
      const arrays = name.includes('article') && !name.includes('delete') ? ['tags','products','content_blocks']
        : name.includes('docs') ? ['blocks'] : name.includes('form_') ? ['guarantees','pieceTypes','stoneOptions','caratOptions','metalOptions']
        : name.includes('content_list') || name.includes('home_group1') || name.includes('relational') || name.includes('reels') || name.includes('hero_') ? ['items'] : []
      if (arrays.some(key => !Array.isArray(record[key]))) throw new Error('Invalid CMS content arrays')
      const objectKey = name.includes('singleton') || name.includes('hero_') ? 'item' : name.includes('home_group1') || name.includes('reels') ? 'section'
        : name.includes('relational') ? 'parent' : name.includes('article') && !name.includes('delete') ? 'post' : name.includes('docs') ? 'page' : name.includes('form_') ? 'settings' : null
      if (objectKey && (!(objectKey in record) || record[objectKey] !== null && (typeof record[objectKey] !== 'object' || Array.isArray(record[objectKey])))) throw new Error('Invalid CMS content object')
    }
    assertSafeCmsIds(result)
    return result as CmsResults[K]
  }
  return { execute, references: createCmsReferenceRepository(db) }
}

import 'server-only'
import type { NavbarSnapshot } from '../../navbar-data'
import type { DbExecutor } from '../query'
import type { AdminActor } from '../../auth/admin-identity-core'

// Fixed deployed signatures from Phase A metadata; no request-selected SQL identifiers.
export const navbarRoutines = {
  navbar_item_save_v1: { sql: "SELECT public.navbar_item_save_v1($1::uuid,$2::uuid,$3::text,$4::uuid,$5::jsonb,$6::jsonb,$7::jsonb,$8::jsonb,$9::jsonb,$10::uuid[],$11::uuid[],$12::bigint[],$13::uuid[]) AS result", args: ["p_actor_id", "p_request_id", "p_expected_revision", "p_item_id", "p_item", "p_sections", "p_links", "p_source_items", "p_featured_card", "p_deleted_section_ids", "p_deleted_link_ids", "p_deleted_source_item_ids", "p_deleted_featured_card_ids"], types: ["uuid", "uuid", "text", "uuid", "jsonb", "jsonb", "jsonb", "jsonb", "jsonb", "uuid[]", "uuid[]", "bigint[]", "uuid[]"] },
  navbar_item_snapshot_v1: { sql: "SELECT public.navbar_item_snapshot_v1($1::uuid) AS result", args: ["p_item_id"], types: ["uuid"] },
  navbar_save_v1: { sql: "SELECT public.navbar_save_v1($1::uuid,$2::uuid,$3::text,$4::jsonb,$5::jsonb,$6::jsonb,$7::jsonb,$8::jsonb,$9::uuid[],$10::uuid[],$11::bigint[],$12::uuid[]) AS result", args: ["p_actor_id", "p_request_id", "p_expected_revision", "p_items", "p_sections", "p_links", "p_source_items", "p_featured_cards", "p_deleted_section_ids", "p_deleted_link_ids", "p_deleted_source_item_ids", "p_deleted_featured_card_ids"], types: ["uuid", "uuid", "text", "jsonb", "jsonb", "jsonb", "jsonb", "jsonb", "uuid[]", "uuid[]", "bigint[]", "uuid[]"] },
  navbar_snapshot_v1: { sql: "SELECT public.navbar_snapshot_v1() AS result", args: [], types: [] },
} as const

export type NavbarArguments = {
  navbar_item_save_v1: { p_request_id: string; p_expected_revision: string; p_item_id: string; p_item: unknown; p_sections: unknown; p_links: unknown; p_source_items: unknown; p_featured_card: unknown; p_deleted_section_ids: readonly string[]; p_deleted_link_ids: readonly string[]; p_deleted_source_item_ids: readonly (string | number)[]; p_deleted_featured_card_ids: readonly string[] }
  navbar_item_snapshot_v1: { p_item_id: string }
  navbar_save_v1: { p_request_id: string; p_expected_revision: string; p_items: unknown; p_sections: unknown; p_links: unknown; p_source_items: unknown; p_featured_cards: unknown; p_deleted_section_ids: readonly string[]; p_deleted_link_ids: readonly string[]; p_deleted_source_item_ids: readonly (string | number)[]; p_deleted_featured_card_ids: readonly string[] }
  navbar_snapshot_v1: Record<string, never>
}
export type NavbarCommand = keyof NavbarArguments

export type NavbarResults = { [K in NavbarCommand]: K extends 'navbar_item_save_v1' | 'navbar_item_snapshot_v1' ? { revision: string } : NavbarSnapshot }

export function createNavbarRepository(db: DbExecutor, actor?: AdminActor) {
  async function execute<K extends NavbarCommand>(name: K, input: NavbarArguments[K]): Promise<NavbarResults[K]> {
    const routine = navbarRoutines[name]
    if (!routine) throw new Error('Unsupported command')
    const supplied = input as Record<string, unknown>
    const values = routine.args.map((key, index) => {
      const value = key === 'p_actor_id' ? actor?.profileId : supplied[key]
      if (value === undefined) throw new Error('Missing trusted actor or routine argument')
      return routine.types[index] === 'jsonb' ? JSON.stringify(value) : value
    })
    let sql: string = routine.sql
    if (name === 'navbar_snapshot_v1') sql = `WITH snapshot AS MATERIALIZED (${routine.sql}) SELECT jsonb_set(result,'{source_items}',coalesce((SELECT jsonb_agg(x.value || jsonb_build_object('id',x.value->>'id') ORDER BY x.ordinality) FROM jsonb_array_elements(result->'source_items') WITH ORDINALITY x),'[]'::jsonb)) AS result FROM snapshot`
    const { rows } = await db.query<{ result: unknown }>(sql, values)
    if (rows.length !== 1 || rows[0].result === null || typeof rows[0].result !== 'object') throw new Error('Invalid database result')
    const result = rows[0].result
    if (name.includes('_list_')) { if (!Array.isArray(result)) throw new Error('Invalid list result') }
    else if (Array.isArray(result)) throw new Error('Invalid snapshot result')
    const record = result as Record<string, unknown>
    if (typeof record.revision !== 'string' || !/^[a-f0-9]{32}$/.test(record.revision)) throw new Error('Invalid navbar revision')
    if (name === 'navbar_snapshot_v1' || name === 'navbar_save_v1') {
      for (const key of ['items', 'sections', 'links', 'source_items', 'featured_cards']) if (!Array.isArray(record[key])) throw new Error('Invalid navbar snapshot')
    }
    return result as NavbarResults[K]
  }
  return { execute }
}

import 'server-only'
import type { z } from 'zod'
import type { portfolioCategoryCreateSchema, portfolioItemCreateSchema } from '../../bespoke-portfolio-validation'
import type { PortfolioCategory, PortfolioItem, BespokeSubmission } from '@/app/dashboard/bespoke/bespoke-client'
import type { DbExecutor } from '../query'
import { enforceVideoSave, videoReferenceSlots } from '../../video-save-admission'

type CategoryInput = z.infer<typeof portfolioCategoryCreateSchema>
type ItemInput = z.infer<typeof portfolioItemCreateSchema>
type PortfolioInputs = { category: CategoryInput; item: ItemInput }
type PortfolioRows = { category: PortfolioCategory; item: PortfolioItem }
const fields = {
  category: ['name','slug','image_path','display_order','status'],
  item: ['title','tag','category_id','media_type','media_path','thumbnail_path','gem_style','gem_color','dark_theme','short_description','display_order','status'],
} as const
const tables = { category: 'bespoke_portfolio_categories', item: 'bespoke_portfolio_items' } as const
const submissionColumns = 'id,full_name,email,phone,country,piece_type,stone_preference,approx_carat,preferred_metal,message,status,created_at'
export function createBespokeRepository(db: DbExecutor) {
  function tableFor(kind: keyof PortfolioRows) {
    if (!Object.hasOwn(tables,kind)) throw new Error('Unsupported portfolio kind')
    return tables[kind]
  }
  async function list<K extends keyof PortfolioRows>(kind: K): Promise<PortfolioRows[K][]> {
    const { rows } = await db.query<{item: PortfolioRows[K]}>(`SELECT to_jsonb(t) AS item FROM public.${tableFor(kind)} t ORDER BY display_order`)
    return rows.map(row => row.item)
  }
  async function exists(kind: keyof PortfolioRows, id: string) {
    return (await db.query(`SELECT id FROM public.${tableFor(kind)} WHERE id=$1::uuid`,[id])).rows.length === 1
  }
  async function save<K extends keyof PortfolioRows>(kind: K, input: PortfolioInputs[K], id?: string, expected?: string, now = new Date().toISOString()): Promise<PortfolioRows[K] | null> {
    const table = tableFor(kind)
    const columns = fields[kind]
    if (videoReferenceSlots(input).size) {
      const previous = id ? (await db.query<{ item: unknown }>(`SELECT to_jsonb(t) AS item FROM public.${table} t WHERE id=$1::uuid FOR UPDATE`, [id])).rows[0]?.item : null
      await enforceVideoSave(db, input, previous)
    }
    const projection = columns.map(column => `(jsonb_populate_record(NULL::public.${table},$1::jsonb)).${column}`).join(',')
    const sql = id
      ? `UPDATE public.${table} SET (${columns.join(',')},updated_at)=(${projection},$4::timestamptz) WHERE id=$2::uuid AND updated_at=$3::timestamptz RETURNING to_jsonb(${table}) AS item`
      : `INSERT INTO public.${table} (${columns.join(',')}) SELECT ${projection} RETURNING to_jsonb(${table}) AS item`
    const { rows } = await db.query<{item: PortfolioRows[K]}>(sql,id ? [JSON.stringify(input),id,expected,now] : [JSON.stringify(input)])
    if (rows.length > 1) throw new Error('Invalid portfolio result')
    return rows[0]?.item ?? null
  }
  async function remove(kind: keyof PortfolioRows, id: string, expected: string) {
    return (await db.query(`DELETE FROM public.${tableFor(kind)} WHERE id=$1::uuid AND updated_at=$2::timestamptz RETURNING id`,[id,expected])).rows.length === 1
  }
  async function submissions(filters: {from?:string;to?:string;q?:string} = {}, bounded = true): Promise<BespokeSubmission[]> {
    const { rows } = await db.query<{item:BespokeSubmission}>(`SELECT to_jsonb(t) AS item FROM (SELECT ${submissionColumns} FROM public.bespoke_submissions WHERE ($1::timestamptz IS NULL OR created_at >= $1::timestamptz) AND ($2::timestamptz IS NULL OR created_at <= $2::timestamptz) ORDER BY created_at DESC ${bounded ? 'LIMIT 1000' : ''}) t`,[filters.from ? `${filters.from}T00:00:00.000Z` : null, filters.to ? `${filters.to}T23:59:59.999Z` : null])
    const q=filters.q?.toLowerCase() ?? ''
    return rows.map(row=>row.item).filter(item=>!q || [item.full_name,item.email,item.phone,item.country,item.piece_type,item.stone_preference,item.approx_carat,item.preferred_metal,item.message,item.status].filter(Boolean).join(' ').toLowerCase().includes(q))
  }
  async function submission(id: string): Promise<BespokeSubmission | null> {
    const {rows}=await db.query<{item:BespokeSubmission}>(`SELECT to_jsonb(t) AS item FROM (SELECT ${submissionColumns} FROM public.bespoke_submissions WHERE id=$1::uuid) t`,[id])
    if(rows.length>1)throw new Error('Invalid submission result')
    return rows[0]?.item ?? null
  }
  return {list,exists,save,remove,submissions,submission}
}

import 'server-only'
import { assertSafeCmsIds, parseCmsJson } from '../../cms-id-safety'
import type { CatalogCategory, CatalogSubcategory, CatalogOption, ProductRecord } from '../../product-catalog'
import type { BlogListItem } from '@/app/dashboard/cms/blog/blog-list-client'
import type { EducationListItem } from '@/app/dashboard/cms/education/education-list-client'
import type { DbExecutor } from '../query'
export type CmsReferenceResults = {
  categories: CatalogCategory[]
  activeCategories: Array<{ id: string; name: string; slug: string }>
  subcategories: CatalogSubcategory[]
  options: CatalogOption[]
  shapes: Array<{ id: string; name: string; slug: string }>
  products: ProductRecord[]
  coupons: Array<{id:number;code:string;title:string;is_active:boolean;usage_limit:number|null;usage_count:number|null}>
  blog: BlogListItem[]
  education: EducationListItem[]
  faqCategories: Array<{id:number;name:string;slug:string;image_path:string|null;image_alt:string;is_active:boolean}>
}
export const cmsReferenceSql = {
  "categories": "SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) AS result FROM (SELECT * FROM public.catalog_categories ORDER BY display_order) r",
  "activeCategories": "SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) AS result FROM (SELECT id,name,slug FROM public.catalog_categories WHERE status='active' ORDER BY display_order) r",
  "subcategories": "SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) AS result FROM (SELECT * FROM public.catalog_subcategories ORDER BY display_order) r",
  "options": "SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) AS result FROM (SELECT * FROM public.catalog_options ORDER BY display_order) r",
  "shapes": "SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) AS result FROM (SELECT id,name,slug FROM public.catalog_stone_shapes WHERE status='active' ORDER BY display_order) r",
  "products": "SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) AS result FROM (SELECT * FROM public.products ORDER BY created_at DESC) r",
  "coupons": "SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) AS result FROM (SELECT id,code,title,is_active,usage_limit,usage_count FROM public.coupons WHERE is_active=true ORDER BY created_at DESC) r",
  "blog": "SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) AS result FROM (SELECT id,slug,title,category,catalog_category_id,author,date_label,read_time,is_published,sort_order,updated_at FROM public.blog_posts ORDER BY sort_order) r",
  "education": "SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) AS result FROM (SELECT id,slug,title,category,author,date_label,read_time,is_published,sort_order,updated_at FROM public.education_posts ORDER BY sort_order) r",
  "faqCategories": "SELECT coalesce(jsonb_agg(to_jsonb(r)),'[]'::jsonb) AS result FROM (SELECT id,name,slug,image_path,image_alt,is_active FROM public.support_faq_categories ORDER BY sort_order) r"
} as const
export function createCmsReferenceRepository(db: DbExecutor) {
  return { async read<K extends keyof CmsReferenceResults>(name: K): Promise<CmsReferenceResults[K]> {
    const sql = cmsReferenceSql[name]
    if (!sql) throw new Error('Unsupported CMS reference')
    const { rows } = await db.query<{result: CmsReferenceResults[K]}>(`WITH snapshot AS MATERIALIZED (${sql}) SELECT result::text AS result FROM snapshot`)
    const result = parseCmsJson(rows[0]?.result)
    if (rows.length !== 1 || !Array.isArray(result)) throw new Error('Invalid CMS references')
    assertSafeCmsIds(result)
    return result as CmsReferenceResults[K]
  } }
}

